import { chromium } from 'playwright';

const PORT = process.env.SB_PORT || '6007';
const STORY_IDS = [
  'commerce-productview--default',
  'commerce-productview--colour-only-no-action-buttons',
  'commerce-productview--stock-message-hidden',
  'commerce-productview--max-quantity-reached',
];

const results = [];

const browser = await chromium.launch();

for (const id of STORY_IDS) {
  const page = await browser.newPage();
  const consoleErrors = [];
  const pageErrors = [];

  page.on('console', (msg) => {
    if (msg.type() === 'error') consoleErrors.push(msg.text());
  });
  page.on('pageerror', (err) => {
    pageErrors.push(err.message);
  });

  const url = `http://localhost:${PORT}/iframe.html?id=${id}&viewMode=story`;
  let navError = null;
  try {
    await page.goto(url, { waitUntil: 'networkidle', timeout: 20000 });
  } catch (e) {
    navError = e.message;
  }

  // Give React a moment to finish rendering / any async error to surface.
  await page.waitForTimeout(1500);

  const bodyText = await page.evaluate(() => document.body.innerText || '');
  const bodyHTML = await page.evaluate(() => document.body.innerHTML || '');
  const rootHTMLLength = await page.evaluate(() => {
    const root = document.getElementById('storybook-root') || document.getElementById('root');
    return root ? root.innerHTML.length : -1;
  });

  // Storybook's error screen renders a heading like "Unhandled error" / "Something went wrong"
  // or shows the error's own name (e.g. "Error") in a big red screen. Also check for the raw
  // preview error overlay class names.
  const hasErrorScreenText =
    /Unhandled error|Something went wrong|The above error occurred|renderPreviewEntry|SB_PREVIEW_API|threw an error/i.test(
      bodyText,
    );
  const hasWebpackOverlay = bodyHTML.includes('webpack-dev-server-client-overlay') || bodyHTML.includes('errors-overlay');

  results.push({
    id,
    url,
    navError,
    consoleErrors,
    pageErrors,
    rootHTMLLength,
    hasErrorScreenText,
    hasWebpackOverlay,
    bodyTextSnippet: bodyText.slice(0, 300),
  });

  await page.close();
}

await browser.close();

console.log(JSON.stringify(results, null, 2));

